import{GovernorCard}from"./GovernorCard.js";export function TimelineItem(e,i){return`\n        <div class="timeline-item" data-target="gov-${i}">\n            <div class="timeline-dot"></div>\n            <div class="timeline-year-label">${e.appointmentDate.split(" ").pop()}</div>\n            <div class="timeline-content">\n                ${GovernorCard(e,i)}\n            </div>\n        </div>\n    `}